package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.hardware.*;import android.os.*;import android.view.*;import android.widget.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;import java.io.*;import java.lang.reflect.*;import java.util.*;
public class DeviceDiagnosticsTest {
 private final android.app.Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private DeviceDiagnosticsActivity activity;
 @After public void finish(){if(activity!=null){ins.runOnMainSync(()->activity.finish());ins.waitForIdleSync();}}
 private void launch()throws Exception{activity=(DeviceDiagnosticsActivity)ins.startActivitySync(new Intent(c,DeviceDiagnosticsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();waitFor(()->get("report")!=null);}
 private Object get(String field)throws Exception{Field f=DeviceDiagnosticsActivity.class.getDeclaredField(field);f.setAccessible(true);return f.get(activity);}
 private void invoke(String name)throws Exception{Method m=DeviceDiagnosticsActivity.class.getDeclaredMethod(name);m.setAccessible(true);ins.runOnMainSync(()->{try{m.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();}
 interface Check{boolean done()throws Exception;}
 private void waitFor(Check check)throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(!check.done()&&SystemClock.elapsedRealtime()<end)Thread.sleep(60);assertTrue(check.done());}
 @Test public void snapshotUsesRealBuildMemoryAndBatteryDoesNotInventMissingValues()throws Exception{DeviceReport report=DeviceReport.collect(c);assertEquals(7,report.sections.size());assertTrue(report.sections.get("Aparelho e processador").contains(Build.MODEL));assertTrue(report.sections.get("Memória e armazenamento").contains("RAM"));assertEquals(DeviceReport.unavailable,DeviceReport.battery(null));String empty=DeviceReport.battery(new Intent());assertTrue(empty,empty.contains("não determinados"));assertTrue(empty,empty.contains("Carga: "+DeviceReport.unavailable));assertFalse(empty,empty.contains("100%"));assertTrue(report.text(Collections.emptyMap()).contains("Nenhum teste concluído"));}
 @Test public void touchCountsActualEventCoverage()throws Exception{DeviceDiagnosticsActivity.TouchSurface view=new DeviceDiagnosticsActivity.TouchSurface(c);ins.runOnMainSync(()->{view.layout(0,0,300,300);for(int y=0;y<3;y++)for(int x=0;x<3;x++){MotionEvent event=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,x*100+50,y*100+50,0);view.onTouchEvent(event);event.recycle();}});assertEquals(9,view.covered());assertEquals(1,view.pointers);}
 @Test public void openingInfoRequestsNoMicrophoneAndCanBuildShareReport()throws Exception{launch();assertNull(get("recorder"));assertNull(get("sensorListener"));assertNull(get("tone"));assertTrue(((Map<?,?>)get("results")).isEmpty());DeviceReport report=(DeviceReport)get("report");String text=report.text(Collections.singletonMap("Som","Observação do usuário"));assertTrue(text.contains("Observação do usuário"));assertTrue(text.contains("não é laudo técnico"));Bitmap screen=ins.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"device-diagnostics.png"))){screen.compress(Bitmap.CompressFormat.PNG,100,out);}finally{screen.recycle();}}
 @Test public void audioTestReleasesFocusAndDoesNotClaimAutomaticPass()throws Exception{launch();invoke("sound");assertNotNull("Audio test must actually create its finite tone",get("tone"));assertTrue(((Map<?,?>)get("results")).isEmpty());ins.runOnMainSync(()->activity.finish());ins.waitForIdleSync();assertNull(get("tone"));assertNull(get("focus"));}
 @Test public void microphoneRecordingIsLocalAndIsDeletedWhenLeaving()throws Exception{launch();invoke("microphone");assertNotNull(((TextView)get("status")).getText().toString(),get("recorder"));File file=(File)get("recording");assertNotNull(file);Thread.sleep(500);ins.runOnMainSync(()->activity.finish());ins.waitForIdleSync();assertNull(get("recorder"));assertNull(get("playback"));assertNull(get("recording"));assertFalse(file.exists());assertTrue(((Map<?,?>)get("results")).isEmpty());}
 @Test public void sensorsUnregisterWhenActivityLeaves()throws Exception{launch();Sensor sensor=((SensorManager)c.getSystemService(Context.SENSOR_SERVICE)).getDefaultSensor(Sensor.TYPE_ACCELEROMETER);assertNotNull("Emulator fixture must expose its accelerometer",sensor);Method m=DeviceDiagnosticsActivity.class.getDeclaredMethod("startSensor",Sensor.class);m.setAccessible(true);ins.runOnMainSync(()->{try{m.invoke(activity,sensor);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();assertNotNull(get("sensorListener"));Thread.sleep(250);ins.runOnMainSync(()->activity.finish());ins.waitForIdleSync();assertNull(get("sensorListener"));assertNull(get("testDialog"));}
}
